import psycopg; conn = psycopg.connect('postgresql://jsp_user:jsp123456@localhost:5432/jsp_erp')
cur = conn.cursor()
cur.execute("""CREATE TABLE IF NOT EXISTS core.service_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), number VARCHAR(20) UNIQUE NOT NULL, customer_id UUID NOT NULL REFERENCES core.customers(id), title VARCHAR(200) NOT NULL, description TEXT, requester VARCHAR(200), problem_description TEXT, status VARCHAR(20) NOT NULL DEFAULT 'pendente', priority VARCHAR(20) NOT NULL DEFAULT 'normal', opening_date DATE NOT NULL DEFAULT CURRENT_DATE, expected_date DATE, start_date TIMESTAMP, completion_date TIMESTAMP, technician VARCHAR(100), equipment VARCHAR(200), brand_model VARCHAR(200), serial_number VARCHAR(100), reported_defect TEXT, technical_diagnosis TEXT, solution TEXT, notes TEXT, start_time TIME, end_time TIME, total_hours VARCHAR(20), initial_km INTEGER, final_km INTEGER, total_km VARCHAR(20), service_amount NUMERIC(10, 2) NOT NULL DEFAULT 0.00, parts_amount NUMERIC(10, 2) NOT NULL DEFAULT 0.00, discount_amount NUMERIC(10, 2) NOT NULL DEFAULT 0.00, total_amount NUMERIC(10, 2) NOT NULL DEFAULT 0.00, warranty_days INTEGER DEFAULT 0, payment_condition VARCHAR(50) NOT NULL DEFAULT 'a_vista', installment_count INTEGER DEFAULT 1, down_payment NUMERIC(10, 2) DEFAULT 0.00, first_installment_date DATE, payment_due_date DATE, payment_description TEXT, payment_status VARCHAR(20) NOT NULL DEFAULT 'pendente', include_images_in_report BOOLEAN DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP, deleted_at TIMESTAMP)""")
cur.execute("""CREATE TABLE IF NOT EXISTS core.service_order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_order_id UUID NOT NULL REFERENCES core.service_orders(id) ON DELETE CASCADE, description VARCHAR(200) NOT NULL, service_type VARCHAR(20) NOT NULL DEFAULT 'hora', quantity NUMERIC(5, 2) NOT NULL DEFAULT 1.00, unit_price NUMERIC(10, 2) NOT NULL DEFAULT 0.00, total_price NUMERIC(10, 2) NOT NULL DEFAULT 0.00, created_at TIMESTAMP NOT NULL DEFAULT now())""")
cur.execute("""CREATE TABLE IF NOT EXISTS core.service_order_products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_order_id UUID NOT NULL REFERENCES core.service_orders(id) ON DELETE CASCADE, product_id UUID REFERENCES core.products(id), description VARCHAR(200) NOT NULL, quantity NUMERIC(10, 3) NOT NULL DEFAULT 1.000, unit_price NUMERIC(10, 2) NOT NULL DEFAULT 0.00, total_price NUMERIC(10, 2) NOT NULL DEFAULT 0.00, created_at TIMESTAMP NOT NULL DEFAULT now())""")
cur.execute("""CREATE TABLE IF NOT EXISTS core.service_order_installments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_order_id UUID NOT NULL REFERENCES core.service_orders(id) ON DELETE CASCADE, installment_number INTEGER NOT NULL, due_date DATE NOT NULL, amount NUMERIC(10, 2) NOT NULL, paid BOOLEAN NOT NULL DEFAULT FALSE, payment_date DATE, created_at TIMESTAMP NOT NULL DEFAULT now())""")
cur.execute("""CREATE TABLE IF NOT EXISTS core.service_order_attachments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_order_id UUID NOT NULL REFERENCES core.service_orders(id) ON DELETE CASCADE, original_filename VARCHAR(255) NOT NULL, stored_filename VARCHAR(255) NOT NULL, file_type VARCHAR(50) NOT NULL, mime_type VARCHAR(100), file_size INTEGER, file_path VARCHAR(500), file_content BYTEA, created_at TIMESTAMP NOT NULL DEFAULT now())""")
conn.commit()
cur.execute("UPDATE core.alembic_version SET version_num = '011_create_service_orders'")
